# The ids of the people on the sheet the user (?user=) watches; with ?asOf=, only those watched by then. 404 for an id never loaded.
load:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ readonly-transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.watch.RespondWithWatched
  govern: [ readonly-transaction ]
package net.officefloor.hq.app.watch;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Val;

/** Record a watch that changed in the audit file: PERSON_WATCHED or PERSON_UNWATCHED. */
public class AuditPersonWatched {
    public void audit(@Val WatchInput input, @Val Person loaded, @Val WatchResponse saved, Audit audit) {
        if (!saved.changed()) {
            return;
        }
        audit.record((saved.watched() ? "PERSON_WATCHED" : "PERSON_UNWATCHED") + " sheet=" + loaded.sheetId()
                + " by=" + input.user() + " name=" + loaded.name());
    }
}
package net.officefloor.hq.app.watch;

import java.util.List;
import net.officefloor.hq.app.sheet.AsOf;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** The ids of the people on the sheet the user watches (none for no user); as of the as-of date, when one is given. */
public class RespondWithWatched {
    public void respond(@PathVariable("sheetId") String sheetId, @RequestParam(name = "user", required = false) String user,
            @RequestParam(name = "asOf", required = false) String asOf,
            WatchRepository watches, ObjectResponse<List<Long>> response) {
        response.send(user == null || user.isBlank() ? List.of() : watches.watchedBy(sheetId.trim(), user.trim(), AsOf.parse(asOf)));
    }
}
