import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithWatch {
    public void respond(@Val WatchResponse saved, ObjectResponse<WatchResponse> response) {
        response.send(saved);
    }
}
package net.officefloor.hq.app.watch;

import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Start or stop the user watching the loaded person; asking for the state already held changes nothing. */
public class SaveWatch {
    public void save(@Val WatchInput input, @Val Person loaded, WatchRepository watches, Out<WatchResponse> saved) {
        boolean now = watches.watching(loaded.sheetId(), loaded.id(), input.user());
        if (now == input.watched()) {
            saved.set(new WatchResponse(loaded.id(), now, false));
            return;
        }
        if (input.watched()) {
            watches.watch(loaded.sheetId(), loaded.id(), input.user());
        } else {
            watches.unwatch(loaded.sheetId(), loaded.id(), input.user());
        }
        saved.set(new WatchResponse(loaded.id(), input.watched(), true));
    }
}
package net.officefloor.hq.app.watch;

import net.officefloor.hq.app.person.InvalidPersonException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the body and refuse it before anything is read or written: a signed-in user and a watched flag. */
public class ValidateWatch {
    public void validate(@RequestBody WatchRequest request, Out<WatchInput> body) throws InvalidPersonException {
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidPersonException("Sign in before watching people.");
        }
        if (request.watched() == null) {
            throw new InvalidPersonException("Say whether to watch this person.");
        }
        body.set(new WatchInput(request.user().trim(), request.watched()));
    }
}
package net.officefloor.hq.app.watch;

/** A validated watch: the signed-in user and whether they are to watch the person. */
public record WatchInput(String user, boolean watched) {
}
package net.officefloor.hq.app.watch;

import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** Who watches which person, per sheet, in the order they started watching. */
@Repository
public class WatchRepository {

    private final JdbcTemplate jdbc;

    public WatchRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The users watching the person, in the order they started watching. */
    public List<String> watchers(String sheetId, long personId) {
        return jdbc.queryForList("SELECT user_name FROM person_watch WHERE sheet_id = ? AND person_id = ? ORDER BY id",
                String.class, sheetId, personId);
    }

    /** The ids of the people on the sheet this user watches; only those watched since the sheet's today was on or
     *  before `end`, when one is given. */
    public List<Long> watchedBy(String sheetId, String user, LocalDate end) {
        return jdbc.queryForList("SELECT person_id FROM person_watch WHERE sheet_id = ? AND user_name = ? "
                + "AND (CAST(? AS DATE) IS NULL OR made_on IS NULL OR made_on <= ?) ORDER BY person_id",
                Long.class, sheetId, user, end, end);
    }

    public boolean watching(String sheetId, long personId, String user) {
        Integer n = jdbc.queryForObject(
                "SELECT COUNT(*) FROM person_watch WHERE sheet_id = ? AND person_id = ? AND user_name = ?",
                Integer.class, sheetId, personId, user);
        return n != null && n > 0;
    }

    public void watch(String sheetId, long personId, String user) {
        jdbc.update("INSERT INTO person_watch (sheet_id, person_id, user_name, made_on) VALUES (?, ?, ?, "
                + "(SELECT today FROM sheet WHERE id = ?))", sheetId, personId, user, sheetId);
    }

    public void unwatch(String sheetId, long personId, String user) {
        jdbc.update("DELETE FROM person_watch WHERE sheet_id = ? AND person_id = ? AND user_name = ?", sheetId, personId,
                user);
    }

    /** Drop everyone's watch of the person. */
    public void drop(String sheetId, long personId) {
        jdbc.update("DELETE FROM person_watch WHERE sheet_id = ? AND person_id = ?", sheetId, personId);
    }
}
