package net.officefloor.hq.app.period;

import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimStatusInput;
import net.officefloor.plugin.variable.Val;

/** Refuse opening a claim whose person already has as many OPEN or PENDING claims in its period as the period's cap. */
public class RefuseCappedOpen {
    public void refuse(@Val ClaimStatusInput input, @Val Claim loaded, PeriodRepository periods, ClaimRepository claims)
            throws CappedPeriodException {
        if (!input.action().equals("open") && !input.action().equals("review")) {
            return;
        }
        Period capped = PeriodCap.reached(loaded, periods, claims);
        if (capped != null) {
            throw new CappedPeriodException(capped);
        }
    }
}
package net.officefloor.hq.app.claim;

/** A status change the claim's current status (or who opened it) does not allow. */
public class ClaimStatusNotAllowedException extends Exception {
    public ClaimStatusNotAllowedException(ClaimStatus from, ClaimStatus to) {
        super("A " + from + " claim cannot become " + to + ".");
    }

    public ClaimStatusNotAllowedException(String message) {
        super(message);
    }
}
package net.officefloor.hq.app.claim;

/** A validated status change: who is making it, the action (open, settle, approve, reject, void or resettle), the status
 *  the claim is to have (a settle above the clerk limit makes it PENDING instead) and, for a reject, the reason, and for a void the
 *  reason chosen from the sheet's list of void reasons (null otherwise). */
public record ClaimStatusInput(String user, String action, ClaimStatus to, String reason) {
}

